function mostFrequentPiece(s: string, maxLetters: number, minSize: number, maxSize: number): number {
  let best = 0;
  for (let len = minSize; len <= maxSize; len++) {
    const seen = new Map<string, number>();
    for (let i = 0; i + len <= s.length; i++) {
      const piece = s.slice(i, i + len);
      if (new Set(piece).size > maxLetters) continue;
      const c = (seen.get(piece) ?? 0) + 1;
      seen.set(piece, c);
      best = Math.max(best, c);
    }
  }
  return best;
}

