function mostFrequentPiece(s: string, maxLetters: number, minSize: number, maxSize: number): number {
  const count = new Array(26).fill(0);
  const seen = new Map<string, number>();
  let distinct = 0, best = 0;
  for (let right = 0; right < s.length; right++) {
    if (count[s.charCodeAt(right) - 97]++ === 0) distinct++;
    const left = right - minSize + 1;
    if (left > 0 && --count[s.charCodeAt(left - 1) - 97] === 0) distinct--;
    if (left >= 0 && distinct <= maxLetters) {
      const piece = s.slice(left, right + 1);
      const c = (seen.get(piece) ?? 0) + 1;
      seen.set(piece, c);
      if (c > best) best = c;
    }
  }
  return best;
}

